package main

import (
	"fmt"
	"math"
	"sort"
	"strings"
)

// ==================================================
// 평가 지표 시스템 (Evaluation Metrics)
// ==================================================

// Evaluator 평가기
type Evaluator struct {
	predictions [][]float64 // 예측 확률 분포
	targets     []int       // 정답 토큰 ID
	vocabSize   int
}

// NewEvaluator 새로운 평가기 생성
func NewEvaluator(vocabSize int) *Evaluator {
	return &Evaluator{
		predictions: make([][]float64, 0),
		targets:     make([]int, 0),
		vocabSize:   vocabSize,
	}
}

// AddPrediction 예측 추가
func (e *Evaluator) AddPrediction(probs []float64, target int) {
	if len(probs) > 0 {
		e.predictions = append(e.predictions, probs)
		e.targets = append(e.targets, target)
	}
}

// CalculatePerplexity 복잡도(Perplexity) 계산
// PPL = exp(-1/N * Σ log(P(target)))
func (e *Evaluator) CalculatePerplexity() float64 {
	if len(e.targets) == 0 {
		return 0.0
	}

	sumLogProb := 0.0
	for i, target := range e.targets {
		if i < len(e.predictions) && target >= 0 && target < len(e.predictions[i]) {
			prob := e.predictions[i][target]
			if prob > 0 {
				sumLogProb += math.Log(prob)
			} else {
				sumLogProb -= 100 // 매우 작은 확률
			}
		}
	}

	avgNegLogProb := -sumLogProb / float64(len(e.targets))
	return math.Exp(avgNegLogProb)
}

// CalculateAccuracy 정확도 계산
// Accuracy = # correct / # total
func (e *Evaluator) CalculateAccuracy() float64 {
	if len(e.targets) == 0 {
		return 0.0
	}

	correct := 0
	for i, target := range e.targets {
		if i < len(e.predictions) {
			// 가장 확률 높은 토큰 선택
			maxProb := 0.0
			maxIdx := 0
			for j, p := range e.predictions[i] {
				if p > maxProb {
					maxProb = p
					maxIdx = j
				}
			}

			if maxIdx == target {
				correct++
			}
		}
	}

	return float64(correct) / float64(len(e.targets))
}

// CalculateTopKAccuracy Top-K 정확도 계산
func (e *Evaluator) CalculateTopKAccuracy(k int) float64 {
	if len(e.targets) == 0 || k <= 0 {
		return 0.0
	}

	correct := 0
	for i, target := range e.targets {
		if i < len(e.predictions) {
			// Top-K 선택
			type probIdx struct {
				prob float64
				idx  int
			}
			var topK []probIdx
			for j, p := range e.predictions[i] {
				topK = append(topK, probIdx{p, j})
			}

			// 정렬
			sort.Slice(topK, func(a, b int) bool {
				return topK[a].prob > topK[b].prob
			})

			// Top-K 확인
			for j := 0; j < k && j < len(topK); j++ {
				if topK[j].idx == target {
					correct++
					break
				}
			}
		}
	}

	return float64(correct) / float64(len(e.targets))
}

// CalculateCrossEntropy 교차 엔트로피 계산
func (e *Evaluator) CalculateCrossEntropy() float64 {
	if len(e.targets) == 0 {
		return 0.0
	}

	totalLoss := 0.0
	for i, target := range e.targets {
		if i < len(e.predictions) && target >= 0 && target < len(e.predictions[i]) {
			prob := e.predictions[i][target]
			if prob > 0 {
				totalLoss -= math.Log(prob)
			} else {
				totalLoss += 100
			}
		}
	}

	return totalLoss / float64(len(e.targets))
}

// CalculateEntropy 엔트로피 계산
func (e *Evaluator) CalculateEntropy() float64 {
	if len(e.predictions) == 0 {
		return 0.0
	}

	totalEntropy := 0.0
	for _, probs := range e.predictions {
		for _, p := range probs {
			if p > 0 {
				totalEntropy -= p * math.Log(p)
			}
		}
	}

	return totalEntropy / float64(len(e.predictions))
}

// ConfusionMatrix 혼동 행렬 (간단한 버전)
type ConfusionMatrix struct {
	TruePositive  int
	TrueNegative  int
	FalsePositive int
	FalseNegative int
}

// CalculatePrecision 정밀도 계산
func (cm *ConfusionMatrix) Precision() float64 {
	total := cm.TruePositive + cm.FalsePositive
	if total == 0 {
		return 0.0
	}
	return float64(cm.TruePositive) / float64(total)
}

// CalculateRecall 재현율 계산
func (cm *ConfusionMatrix) Recall() float64 {
	total := cm.TruePositive + cm.FalseNegative
	if total == 0 {
		return 0.0
	}
	return float64(cm.TruePositive) / float64(total)
}

// CalculateF1Score F1 스코어 계산
func (cm *ConfusionMatrix) F1Score() float64 {
	precision := cm.Precision()
	recall := cm.Recall()
	if precision+recall == 0 {
		return 0.0
	}
	return 2 * (precision * recall) / (precision + recall)
}

// ==================================================
// BLEU Score 계산
// ==================================================

// BLEUScorer BLEU 스코어 계산기
type BLEUScorer struct {
	weights [4]float64 // 1-gram, 2-gram, 3-gram, 4-gram 가중치
}

// NewBLEUScorer 새로운 BLEU 스코어 계산기 생성
func NewBLEUScorer() *BLEUScorer {
	return &BLEUScorer{
		weights: [4]float64{0.25, 0.25, 0.25, 0.25}, // 균등 가중치
	}
}

// CalculateNGramMatches N-gram 일치도 계산
func (b *BLEUScorer) CalculateNGramMatches(reference []int, hypothesis []int, n int) float64 {
	if n > len(reference) || n > len(hypothesis) || n <= 0 {
		return 0.0
	}

	matches := 0
	for i := 0; i <= len(hypothesis)-n; i++ {
		for j := 0; j <= len(reference)-n; j++ {
			match := true
			for k := 0; k < n; k++ {
				if hypothesis[i+k] != reference[j+k] {
					match = false
					break
				}
			}
			if match {
				matches++
				break
			}
		}
	}

	denominator := len(hypothesis) - n + 1
	if denominator <= 0 {
		return 0.0
	}

	return float64(matches) / float64(denominator)
}

// CalculateBLEU BLEU 스코어 계산
func (b *BLEUScorer) CalculateBLEU(reference []int, hypothesis []int) float64 {
	if len(hypothesis) == 0 {
		return 0.0
	}

	bleuScore := 0.0
	for n := 1; n <= 4; n++ {
		ngramMatch := b.CalculateNGramMatches(reference, hypothesis, n)
		bleuScore += b.weights[n-1] * ngramMatch
	}

	// 가설이 참조보다 짧으면 페널티
	if len(hypothesis) < len(reference) {
		brevityPenalty := math.Exp(1.0 - float64(len(reference))/float64(len(hypothesis)))
		bleuScore *= brevityPenalty
	}

	return bleuScore
}

// ==================================================
// 성능 보고서
// ==================================================

// EvaluationReport 평가 보고서
type EvaluationReport struct {
	Perplexity      float64
	Accuracy        float64
	TopK5Accuracy   float64
	TopK10Accuracy  float64
	CrossEntropy    float64
	Entropy         float64
	AverageBLEU     float64
	SampleSize      int
	VocabSize       int
}

// PrintReport 보고서 출력
func (r *EvaluationReport) PrintReport() {
	fmt.Println("\n════════════════════════════════════════════════════════")
	fmt.Println("📊 EVALUATION REPORT")
	fmt.Println("════════════════════════════════════════════════════════")

	fmt.Printf("\n🎯 Main Metrics:\n")
	fmt.Printf("  Perplexity:         %.4f\n", r.Perplexity)
	fmt.Printf("  Cross-Entropy Loss: %.4f\n", r.CrossEntropy)
	fmt.Printf("  Entropy:            %.4f\n", r.Entropy)

	fmt.Printf("\n📈 Accuracy Metrics:\n")
	fmt.Printf("  Top-1 Accuracy:     %.2f%%\n", r.Accuracy*100)
	fmt.Printf("  Top-5 Accuracy:     %.2f%%\n", r.TopK5Accuracy*100)
	fmt.Printf("  Top-10 Accuracy:    %.2f%%\n", r.TopK10Accuracy*100)

	fmt.Printf("\n🔤 Translation Metrics:\n")
	fmt.Printf("  Avg BLEU Score:     %.4f\n", r.AverageBLEU)

	fmt.Printf("\n📊 Dataset Info:\n")
	fmt.Printf("  Sample Size:        %d\n", r.SampleSize)
	fmt.Printf("  Vocabulary Size:    %d\n", r.VocabSize)

	fmt.Println("\n════════════════════════════════════════════════════════")
}

// ==================================================
// 학습 분석
// ==================================================

// TrainingAnalysis 학습 분석
type TrainingAnalysis struct {
	EpochLosses    []float64
	ValLosses      []float64
	EpochMetrics   []EvaluationReport
	BestEpoch      int
	BestValLoss    float64
	ConvergenceRate float64
	Stability      float64
}

// AnalyzeConvergence 수렴 분석
func AnalyzeConvergence(losses []float64) float64 {
	if len(losses) < 2 {
		return 0.0
	}

	// 초기 5개와 마지막 5개 비교
	minStart := 5
	minEnd := 5
	if len(losses) < minStart+minEnd {
		minStart = len(losses) / 2
		minEnd = len(losses) / 2
	}

	avgStart := 0.0
	for i := 0; i < minStart && i < len(losses); i++ {
		avgStart += losses[i]
	}
	avgStart /= float64(minStart)

	avgEnd := 0.0
	for i := len(losses) - minEnd; i < len(losses); i++ {
		if i >= 0 {
			avgEnd += losses[i]
		}
	}
	avgEnd /= float64(minEnd)

	if avgStart == 0 {
		return 0.0
	}

	return (avgStart - avgEnd) / avgStart * 100
}

// AnalyzeStability 안정성 분석
func AnalyzeStability(losses []float64) float64 {
	if len(losses) < 2 {
		return 100.0
	}

	// 연속적인 변화의 절대값 평균
	totalChange := 0.0
	for i := 1; i < len(losses); i++ {
		totalChange += math.Abs(losses[i] - losses[i-1])
	}
	avgChange := totalChange / float64(len(losses)-1)

	// 안정성 = 변화가 적을수록 높음 (100% 기준)
	// 정규화: 평균 손실 대비 변화율
	avgLoss := 0.0
	for _, l := range losses {
		avgLoss += l
	}
	avgLoss /= float64(len(losses))

	if avgLoss == 0 {
		return 100.0
	}

	stability := 100.0 - (avgChange/avgLoss)*100.0
	if stability < 0 {
		stability = 0
	}
	return stability
}

