package main

import (
	"encoding/json"
	"fmt"
	"net/http"
)

// ==================================================
// 평가 API 엔드포인트
// ==================================================

// EvalRequest 평가 요청
type EvalRequest struct {
	ModelCheckpoint string    `json:"model_checkpoint"`
	DataType        string    `json:"data_type"` // "train", "val", "test"
	Metrics         []string  `json:"metrics"`   // "perplexity", "accuracy", "bleu"
}

// EvalResponse 평가 응답
type EvalResponse struct {
	Timestamp   string                 `json:"timestamp"`
	ModelID     string                 `json:"model_id"`
	DataType    string                 `json:"data_type"`
	SampleCount int                    `json:"sample_count"`
	Metrics     map[string]interface{} `json:"metrics"`
	Duration    float64                `json:"duration_seconds"`
	Status      string                 `json:"status"`
}

// MetricsComparisonRequest 메트릭 비교 요청
type MetricsComparisonRequest struct {
	Model1Checkpoint string `json:"model1_checkpoint"`
	Model2Checkpoint string `json:"model2_checkpoint"`
	DataType         string `json:"data_type"`
}

// MetricsComparisonResponse 메트릭 비교 응답
type MetricsComparisonResponse struct {
	Model1    string                 `json:"model1"`
	Model2    string                 `json:"model2"`
	Metrics   map[string]interface{} `json:"metrics"`
	Winner    string                 `json:"winner"`
	Advantage map[string]float64     `json:"advantage_percent"`
	Status    string                 `json:"status"`
}

// EvaluateModel 모델 평가 API
func EvaluateModel(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req EvalRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, fmt.Sprintf("Invalid request: %v", err), http.StatusBadRequest)
		return
	}

	// 메트릭 계산 (현재는 더미 데이터)
	metrics := make(map[string]interface{})

	if req.Metrics == nil || len(req.Metrics) == 0 {
		req.Metrics = []string{"perplexity", "accuracy", "bleu"}
	}

	for _, metric := range req.Metrics {
		switch metric {
		case "perplexity":
			metrics["perplexity"] = 25.34
			metrics["perplexity_trend"] = "decreasing"
		case "accuracy":
			metrics["top1_accuracy"] = 0.68
			metrics["top5_accuracy"] = 0.92
			metrics["top10_accuracy"] = 0.96
		case "bleu":
			metrics["bleu_score"] = 0.42
			metrics["bleu_1gram"] = 0.55
			metrics["bleu_2gram"] = 0.48
			metrics["bleu_3gram"] = 0.35
			metrics["bleu_4gram"] = 0.25
		case "entropy":
			metrics["entropy"] = 8.23
			metrics["max_entropy"] = 13.45 // log(vocab_size)
		case "crossentropy":
			metrics["crossentropy"] = 3.23
		}
	}

	resp := EvalResponse{
		Timestamp:   getCurrentTimestamp(),
		ModelID:     req.ModelCheckpoint,
		DataType:    req.DataType,
		SampleCount: 256,
		Metrics:     metrics,
		Duration:    2.34,
		Status:      "success",
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resp)
}

// CompareModels 모델 비교 API
func CompareModels(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
