// EvalRequest 평가 요청
type EvalRequest struct {
	ModelCheckpoint string    `json:"model_checkpoint"`
	DataType        string    `json:"data_type"` // "train", "val", "test"
	Metrics         []string  `json:"metrics"`   // "perplexity", "accuracy", "bleu"
}

