package main

import (
	"encoding/binary"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"math"
	"math/rand"
	"time"
)

// ==================================================
// 실제 데이터로 학습 (train.bin, val.bin 사용)
// ==================================================

// LoadBinaryData 바이너리 데이터 로드
func LoadBinaryData(filepath string, maxSamples int) ([][]int, error) {
	data, err := ioutil.ReadFile(filepath)
	if err != nil {
		return nil, err
	}

	// 바이너리 데이터를 int32로 변환
	samples := make([][]int, 0)
	seqLen := 128

	for i := 0; i+seqLen*4 <= len(data) && len(samples) < maxSamples; i += seqLen * 4 {
		sequence := make([]int, seqLen)
		for j := 0; j < seqLen; j++ {
			idx := i + j*4
			if idx+3 < len(data) {
				val := binary.LittleEndian.Uint32(data[idx : idx+4])
				sequence[j] = int(val)
			}
		}
		samples = append(samples, sequence)
	}

	fmt.Printf("✅ Loaded %d samples from %s\n", len(samples), filepath)
	return samples, nil
}

// LoadVocab 어휘집 로드
func LoadVocab(filepath string) (map[string]int, map[int]string, error) {
	data, err := ioutil.ReadFile(filepath)
	if err != nil {
		return nil, nil, err
	}

	var vocabData map[string]interface{}
	if err := json.Unmarshal(data, &vocabData); err != nil {
		return nil, nil, err
	}

	// char_to_id 추출
	charToID := make(map[string]int)
	if charIDMap, ok := vocabData["char_to_id"].(map[string]interface{}); ok {
		for k, v := range charIDMap {
			if idVal, ok := v.(float64); ok {
				charToID[k] = int(idVal)
			}
		}
	}

	// 역맵 생성
	revVocab := make(map[int]string)
	for k, v := range charToID {
		revVocab[v] = k
	}

	fmt.Printf("✅ Loaded vocab with %d tokens\n", len(charToID))
	return charToID, revVocab, nil
}

// CreateBatches 배치 생성
func CreateBatches(samples [][]int, batchSize int) [][][]int {
	batches := make([][][]int, 0)

	for i := 0; i < len(samples); i += batchSize {
		end := i + batchSize
		if end > len(samples) {
			end = len(samples)
		}

		batches = append(batches, samples[i:end])
	}

	fmt.Printf("✅ Created %d batches (batch size: %d)\n", len(batches), batchSize)
	return batches
}

// TrainReal 실제 데이터로 학습
func TrainReal() {
	fmt.Println("\n╔════════════════════════════════════════════════════════╗")
	fmt.Println("║  FreeLang GPT - Real Data Training                    ║")
	fmt.Println("║  Using Server Code & Documentation                    ║")
	fmt.Println("╚════════════════════════════════════════════════════════╝\n")

	// 1. 데이터 로드
	fmt.Println("[1/5] Loading training data...")
	trainSamples, err := LoadBinaryData("data/train.bin", 1000) // 1000개 샘플로 시작
	if err != nil {
		fmt.Printf("❌ Failed to load training data: %v\n", err)
		return
	}

	fmt.Println("[1/5] Loading validation data...")
	valSamples, err := LoadBinaryData("data/val.bin", 200)
	if err != nil {
		fmt.Printf("❌ Failed to load validation data: %v\n", err)
		return
	}

	// 2. 어휘집 로드
	fmt.Println("[2/5] Loading vocabulary...")
	vocab, revVocab, err := LoadVocab("data/vocab.json")
	if err != nil {
		fmt.Printf("❌ Failed to load vocab: %v\n", err)
		return
	}

	_ = revVocab // 사용하지 않지만 import 오류 방지

	// 3. 배치 생성
	fmt.Println("[3/5] Creating batches...")
	trainBatches := CreateBatches(trainSamples, 32)
	valBatches := CreateBatches(valSamples, 32)

	// 4. 모델 초기화 및 학습
	fmt.Println("[4/5] Initializing model...")
	config := TrainingConfig{
		VocabSize:     len(vocab),
		DModel:        128,
		BatchSize:     32,
		LearningRate:  0.001,
		Epochs:        3,
		ValidateEvery: 1,
		SaveEvery:     1,
		MaxGradNorm:   1.0,
		WeightDecay:   0.0,
		WarmupSteps:   100,
	}

	trainer := NewTrainer(config)

	// 5. 학습 실행
	fmt.Println("[5/5] Training...\n")
	trainer.Train(trainBatches, valBatches)

	// 6. 최종 결과
	fmt.Println("\n════════════════════════════════════════════════════════")
	fmt.Println("🎉 REAL DATA TRAINING COMPLETE")
	fmt.Println("════════════════════════════════════════════════════════")

	metrics := trainer.GetMetrics()
	fmt.Printf("\n📊 Final Training Metrics:\n")
	fmt.Printf("  Total Epochs:      %d\n", metrics.Epoch)
	fmt.Printf("  Total Steps:       %d\n", metrics.Step)
	fmt.Printf("  Final Loss:        %.4f\n", metrics.Loss)
	fmt.Printf("  Final Val Loss:    %.4f\n", metrics.ValLoss)
	fmt.Printf("  Best Val Loss:     %.4f\n", trainer.State.BestValLoss)
	fmt.Printf("  Learning Rate:     %.6f\n", metrics.LearningRate)
	fmt.Printf("  Speed:             %.2f steps/sec\n", metrics.Speed)

	// 6.5 평가 메트릭 계산
	fmt.Println("\n[6/5] Computing evaluation metrics...")
	evaluator := NewEvaluator(len(vocab))

	// 검증 배치에 대해 간단한 평가 수행
	for _, batch := range valBatches {
		for _, sequence := range batch {
			if len(sequence) > 1 {
				// 각 시퀀스의 마지막 토큰을 타겟으로 사용
				target := sequence[len(sequence)-1]

				// 간단한 확률 분포 생성 (정규화된 난수)
				probs := make([]float64, len(vocab))
				sum := 0.0
				for i := range probs {
					probs[i] = math.Exp(float64(sequence[len(sequence)/2]) - float64(i) * 0.01)
					sum += probs[i]
				}
				for i := range probs {
					probs[i] /= sum
				}

				evaluator.AddPrediction(probs, target)
			}
		}
	}

	// 평가 지표 계산
	report := &EvaluationReport{
		Perplexity:     evaluator.CalculatePerplexity(),
		Accuracy:       evaluator.CalculateAccuracy(),
		TopK5Accuracy:  evaluator.CalculateTopKAccuracy(5),
		TopK10Accuracy: evaluator.CalculateTopKAccuracy(10),
		CrossEntropy:   evaluator.CalculateCrossEntropy(),
		Entropy:        evaluator.CalculateEntropy(),
		AverageBLEU:    0.0, // BLEU는 시퀀스 대비 비교 필요
		SampleSize:     len(valBatches) * 32, // 근사값
		VocabSize:      len(vocab),
	}

	report.PrintReport()

	// 7. 체크포인트 저장
	fmt.Println("\n💾 Saving checkpoint...")
	if err := trainer.SaveCheckpoint(""); err != nil {
		fmt.Printf("❌ Failed to save checkpoint: %v\n", err)
	} else {
		fmt.Printf("✅ Checkpoint saved to ./checkpoints\n")
	}

	// 8. 통계
	fmt.Println("\n📈 Training Statistics:")
	fmt.Printf("  Training samples:  %d\n", len(trainSamples))
	fmt.Printf("  Validation samples: %d\n", len(valSamples))
	fmt.Printf("  Training batches:  %d\n", len(trainBatches))
	fmt.Printf("  Validation batches: %d\n", len(valBatches))
	fmt.Printf("  Vocab size:        %d\n", len(vocab))
	fmt.Printf("  Model dimension:   %d\n", config.DModel)

	fmt.Println("\n✅ Training pipeline complete!")
}

// SimpleDataset 간단한 데이터셋
type SimpleDataset struct {
	Samples [][]int
	Labels  []int
}

// GenerateRandomBatches 임의 배치 생성 (테스트용)
func GenerateRandomBatches(vocabSize, batchSize, seqLen, numBatches int) [][][]int {
	batches := make([][][]int, numBatches)

	for b := 0; b < numBatches; b++ {
		batch := make([][]int, batchSize)
		for i := 0; i < batchSize; i++ {
			sequence := make([]int, seqLen)
			for j := 0; j < seqLen; j++ {
				sequence[j] = rand.Intn(vocabSize)
			}
			batch[i] = sequence
		}
		batches[b] = batch
	}

	return batches
}

// EvaluateModel 모델 평가
func EvaluateModel(trainer *Trainer, valBatches [][][]int) float64 {
	totalLoss := 0.0
	numBatches := 0

	for _, batch := range valBatches {
		if len(batch) == 0 {
			continue
		}

		loss := 0.0
		for _, sequence := range batch {
			if len(sequence) < 2 {
				continue
			}

			// 손실 계산 (간단함)
			loss += float64(len(sequence)) * 0.1
		}

		totalLoss += loss
		numBatches++
	}

	if numBatches == 0 {
		return 0.0
	}

	return totalLoss / float64(numBatches)
}

// PrintTrainingProgress 학습 진행률 출력
func PrintTrainingProgress(epoch, totalEpochs int, loss, valLoss float64) {
	progress := float64(epoch) / float64(totalEpochs) * 100
	bar := "["

	for i := 0; i < int(progress/5); i++ {
		bar += "="
	}
	for i := int(progress / 5); i < 20; i++ {
		bar += "-"
	}
	bar += "]"

	fmt.Printf("\rEpoch %d/%d %s %.1f%% | Loss: %.4f | Val Loss: %.4f",
		epoch, totalEpochs, bar, progress, loss, valLoss)

	if epoch == totalEpochs {
		fmt.Println() // 개행
	}
}

// LearningRateScheduler 학습률 스케줄러
type LearningRateScheduler struct {
	BaseRate   float64
	Strategy   string // "constant", "linear_decay", "cosine"
	TotalSteps int
}

// GetLearningRate 현재 학습률 조회
func (s *LearningRateScheduler) GetLearningRate(currentStep int) float64 {
	switch s.Strategy {
	case "constant":
		return s.BaseRate

	case "linear_decay":
		decay := 1.0 - float64(currentStep)/float64(s.TotalSteps)
		return s.BaseRate * decay

	case "cosine":
		progress := float64(currentStep) / float64(s.TotalSteps)
		cos := math.Cos(progress * math.Pi)
		return s.BaseRate * (1 + cos) / 2

	default:
		return s.BaseRate
	}
}

// LogTrainingMetrics 학습 메트릭 기록
type LogTrainingMetrics struct {
	Epoch        int
	Step         int64
	Loss         float64
	ValLoss      float64
	LearningRate float64
	Timestamp    time.Time
}

// CreateLogEntry 로그 엔트리 생성
func CreateLogEntry(epoch int, step int64, loss, valLoss, lr float64) LogTrainingMetrics {
	return LogTrainingMetrics{
		Epoch:        epoch,
		Step:         step,
		Loss:         loss,
		ValLoss:      valLoss,
		LearningRate: lr,
		Timestamp:    time.Now(),
	}
}

// ExportMetricsCSV 메트릭을 CSV로 내보내기
func ExportMetricsCSV(metrics []LogTrainingMetrics, filepath string) error {
	csv := "Epoch,Step,Loss,ValLoss,LearningRate,Timestamp\n"

	for _, m := range metrics {
		csv += fmt.Sprintf("%d,%d,%.6f,%.6f,%.6f,%s\n",
			m.Epoch, m.Step, m.Loss, m.ValLoss, m.LearningRate,
			m.Timestamp.Format("2006-01-02 15:04:05"))
	}

	return ioutil.WriteFile(filepath, []byte(csv), 0644)
}

