	fmt.Printf("\nMethod 2: Real Gradients\n")
	fmt.Printf("  Epochs:            %d\n", trainer2.metrics.Epoch)
	fmt.Printf("  Final Train Loss:  %.4f\n", trainer2.metrics.Loss)
	fmt.Printf("  Best Val Loss:     %.4f\n", trainer2.state.BestValLoss)
	fmt.Printf("  Speed:             %.1f steps/sec\n", trainer2.metrics.Speed)

	// 어느 것이 더 좋은지
	fmt.Println("\n🏆 Better Method:")
	if trainer2.state.BestValLoss < trainer1.state.BestValLoss {
		improvement := (trainer1.state.BestValLoss - trainer2.state.BestValLoss) / trainer1.state.BestValLoss * 100
		fmt.Printf("  Method 2 (Real Gradients) is %.1f%% better\n", improvement)
	} else {
		improvement := (trainer2.state.BestValLoss - trainer1.state.BestValLoss) / trainer2.state.BestValLoss * 100
		fmt.Printf("  Method 1 (Loss Decay) is %.1f%% better\n", improvement)
	}

	fmt.Println("\n✅ Advanced training tests complete!")
}

