	fmt.Println("════════════════════════════════════════════════════════")

	config3 := LargeModelConfig{
		VocabSize:    len(vocab),
		DModel:       1024,
		NumHeads:     32,
		NumLayers:    8,
		FFNDim:       4096,
		MaxSeqLen:    128,
		LearningRate: 0.0001,
		BatchSize:    32,
		Epochs:       15,
