	}

	trainLargeModel(trainBatches, valBatches, vocab, config3)

	// 최종 비교
	fmt.Println("\n════════════════════════════════════════════════════════")
	fmt.Println("🏆 MODEL SIZE COMPARISON")
	fmt.Println("════════════════════════════════════════════════════════\n")

	models := []struct {
		name   string
		config LargeModelConfig
	}{
		{"Medium (256D, 4L)", config1},
		{"Large (512D, 6L)", config2},
		{"XLarge (1024D, 8L)", config3},
	}

	fmt.Println("Model            | Total Params | Training Speed")
	fmt.Println("-----------------|--------------|----------------")

	for _, m := range models {
		embedParams := m.config.VocabSize * m.config.DModel
		attnParams := m.config.NumLayers * 4 * m.config.DModel * m.config.DModel
		ffnParams := m.config.NumLayers * 2 * m.config.DModel * m.config.FFNDim
