		fmt.Printf("%-16s | %.1fM         | ~%.1f steps/sec\n",
			m.name, float64(totalParams)/1e6, 100.0*math.Exp(-float64(m.config.DModel)/500))
	}

	fmt.Println("\n✅ All tests complete!")
}

