					valLoss += loss
				}
			}

			valBatchCount++
		}

		if valBatchCount > 0 {
			totalValCount := 0
			for _, batch := range valBatches {
				totalValCount += len(batch)
			}
			if totalValCount > 0 {
				valLoss /= float64(totalValCount)
			}
		}

		losses = append(losses, epochLoss)
		valLosses = append(valLosses, valLoss)

		// 에포크 시간 계산
		epochTime := time.Since(epochStartTime).Seconds()
		throughput := float64(totalSteps) / time.Since(startTime).Seconds()

		// Perplexity 계산
		perplexity := math.Exp(valLoss)

		// 이전 검증 손실과 비교 (개선 여부)
		improved := ""
		if valLoss < bestValLoss {
