package main

import (
	"fmt"
	"math"
	"math/rand"
)

// ==================================================
// 텍스트 생성 (Text Generation)
// ==================================================

// Generator 텍스트 생성기
type Generator struct {
	vocabSize   int
	modelDim    int
	maxSeqLen   int
	temperature float64
}

// NewGenerator 새로운 생성기 생성
func NewGenerator(vocabSize, modelDim, maxSeqLen int) *Generator {
	return &Generator{
		vocabSize:   vocabSize,
		modelDim:    modelDim,
		maxSeqLen:   maxSeqLen,
		temperature: 1.0,
	}
}

// SetTemperature 온도 설정 (낮을수록 결정적, 높을수록 창의적)
func (g *Generator) SetTemperature(temp float64) {
	if temp > 0 {
		g.temperature = temp
	}
}

// predictNextToken 다음 토큰 예측 (시뮬레이션)
func (g *Generator) predictNextToken(sequence []int) int {
	if len(sequence) == 0 {
		return rand.Intn(g.vocabSize)
	}

	// 마지막 토큰 기반으로 logits 생성 (시뮬레이션)
	lastToken := sequence[len(sequence)-1]
	logits := make([]float64, g.vocabSize)

	// 마지막 토큰과 관련된 토큰들에 높은 logits 부여
	for i := 0; i < g.vocabSize; i++ {
		// 토큰 간 유사도 (매우 간단한 시뮬레이션)
		distance := float64((lastToken - i) * (lastToken - i))
		logits[i] = math.Exp(-distance / float64(g.vocabSize*100)) * 10
	}

	// Softmax with temperature
	return g.sampleFromLogits(logits)
}

// sampleFromLogits logits에서 샘플링
func (g *Generator) sampleFromLogits(logits []float64) int {
	// Temperature 적용
	for i := range logits {
		logits[i] /= g.temperature
	}

	// Softmax
	maxLogit := logits[0]
	for _, l := range logits {
		if l > maxLogit {
			maxLogit = l
		}
	}

	sumExp := 0.0
	for _, l := range logits {
		sumExp += math.Exp(l - maxLogit)
	}

	probs := make([]float64, len(logits))
	for i, l := range logits {
		probs[i] = math.Exp(l-maxLogit) / sumExp
	}

	// Cumulative sampling
	r := rand.Float64()
	cumsum := 0.0

	for i, p := range probs {
		cumsum += p
		if r < cumsum {
			return i
		}
	}

	return len(logits) - 1
}

// GenerateGreedy Greedy decoding (항상 가장 확률 높은 토큰 선택)
func (g *Generator) GenerateGreedy(prompt []int, maxTokens int) []int {
	result := make([]int, len(prompt))
	copy(result, prompt)

	for i := 0; i < maxTokens && len(result) < g.maxSeqLen; i++ {
		nextToken := g.predictNextToken(result)
		result = append(result, nextToken)
	}

	return result
}

// GenerateWithSampling 샘플링으로 생성 (창의적)
func (g *Generator) GenerateWithSampling(prompt []int, maxTokens int) []int {
	result := make([]int, len(prompt))
	copy(result, prompt)

	for i := 0; i < maxTokens && len(result) < g.maxSeqLen; i++ {
		nextToken := g.predictNextToken(result)
		result = append(result, nextToken)
	}

	return result
}

// GenerateBeamSearch Beam search (상위 k개 경로 탐색)
func (g *Generator) GenerateBeamSearch(prompt []int, maxTokens, beamWidth int) []int {
	// 간단한 구현: greedy와 동일
	return g.GenerateGreedy(prompt, maxTokens)
}

// decodeTokens 토큰 ID를 텍스트로 변환
func decodeTokens(tokens []int, vocab map[string]int) string {
	// 역맵 생성
	revVocab := make(map[int]string)
	for k, v := range vocab {
		revVocab[v] = k
	}

	text := ""
	for _, tokenID := range tokens {
		if ch, ok := revVocab[tokenID]; ok {
			text += ch
		} else {
			text += fmt.Sprintf("[UNK:%d]", tokenID)
		}
	}

	return text
}

// encodeText 텍스트를 토큰 ID로 변환
func encodeText(text string, vocab map[string]int) []int {
	tokens := make([]int, 0)

	for _, ch := range text {
		if id, ok := vocab[string(ch)]; ok {
			tokens = append(tokens, id)
		}
	}

	return tokens
}

// GenerateText 사용자 친화적 텍스트 생성
func GenerateText(prompt string, maxTokens int, vocab map[string]int, temperature float64, method string) (string, []int) {
	generator := NewGenerator(len(vocab), 1024, 128)
	generator.SetTemperature(temperature)

	// 프롬프트 인코딩
	promptTokens := encodeText(prompt, vocab)

	var generatedTokens []int

	switch method {
	case "greedy":
		generatedTokens = generator.GenerateGreedy(promptTokens, maxTokens)
	case "sampling":
		generatedTokens = generator.GenerateWithSampling(promptTokens, maxTokens)
	case "beam":
		generatedTokens = generator.GenerateBeamSearch(promptTokens, maxTokens, 5)
	default:
		generatedTokens = generator.GenerateGreedy(promptTokens, maxTokens)
	}

	// 토큰 디코딩
	text := decodeTokens(generatedTokens, vocab)

	return text, generatedTokens
}

// testTextGeneration 텍스트 생성 테스트
func testTextGeneration() {
	fmt.Println("\n╔════════════════════════════════════════════════════════╗")
	fmt.Println("║  Text Generation - 한글 텍스트 자동 생성               ║")
	fmt.Println("║  LLM Inference & Decoding                             ║")
	fmt.Println("╚════════════════════════════════════════════════════════╝\n")

	// 어휘집 로드
	fmt.Println("[1/3] Loading vocabulary...")
	vocab, revVocab, err := LoadVocab("data/vocab.json")
	if err != nil {
		fmt.Printf("❌ Failed to load vocab: %v\n", err)
		return
	}

	fmt.Printf("✅ Loaded %d tokens\n\n", len(vocab))

	// 프롬프트 목록
	prompts := []string{
		"프리랭",
		"함수형",
		"컴파일러",
		"언어",
		"데이터",
	}

	fmt.Println("════════════════════════════════════════════════════════")
	fmt.Println("🎯 TEST 1: Greedy Decoding (결정적)")
	fmt.Println("════════════════════════════════════════════════════════\n")

	for i, prompt := range prompts[:3] {
		text, tokens := GenerateText(prompt, 20, vocab, 1.0, "greedy")

		fmt.Printf("📝 Prompt %d: \"%s\"\n", i+1, prompt)
		fmt.Printf("   Generated: \"%s\"\n", text)
		fmt.Printf("   Tokens: %v\n", tokens[:min(len(tokens), 15)])
		fmt.Printf("   Length: %d tokens\n\n", len(tokens))
	}

	// Test 2: Temperature Sampling
	fmt.Println("════════════════════════════════════════════════════════")
	fmt.Println("🎯 TEST 2: Sampling with Temperature (창의적)")
	fmt.Println("════════════════════════════════════════════════════════\n")

	temperatures := []float64{0.5, 1.0, 1.5}

	for _, temp := range temperatures {
		fmt.Printf("🌡️  Temperature: %.1f\n", temp)

		text, tokens := GenerateText("프리", 15, vocab, temp, "sampling")

		fmt.Printf("   Generated: \"%s\"\n", text)
		fmt.Printf("   Tokens: %v\n\n", tokens[:min(len(tokens), 10)])
	}

	// Test 3: 다양한 방법 비교
	fmt.Println("════════════════════════════════════════════════════════")
	fmt.Println("🎯 TEST 3: Decoding Methods Comparison")
	fmt.Println("════════════════════════════════════════════════════════\n")

	methods := []struct {
		name string
		temp float64
	}{
		{"Greedy", 1.0},
		{"Sampling (Low Temp)", 0.3},
		{"Sampling (High Temp)", 1.5},
	}

	prompt := "언어"

	for _, m := range methods {
		text, tokens := GenerateText(prompt, 25, vocab, m.temp, "sampling")

		fmt.Printf("📌 Method: %s (Temperature: %.1f)\n", m.name, m.temp)
		fmt.Printf("   Input: \"%s\" (%d tokens)\n", prompt, len(encodeText(prompt, vocab)))
		fmt.Printf("   Output: \"%s\"\n", text)
		fmt.Printf("   Generated Length: %d tokens\n\n", len(tokens)-len(encodeText(prompt, vocab)))
	}

	// Test 4: 긴 시퀀스 생성
	fmt.Println("════════════════════════════════════════════════════════")
	fmt.Println("🎯 TEST 4: Long Sequence Generation")
	fmt.Println("════════════════════════════════════════════════════════\n")

	longPrompt := "프리랭은"
	text, tokens := GenerateText(longPrompt, 50, vocab, 0.8, "sampling")

	fmt.Printf("📝 Long Prompt: \"%s\"\n", longPrompt)
	fmt.Printf("📄 Generated Text:\n\"%s\"\n\n", text)
	fmt.Printf("📊 Statistics:\n")
	fmt.Printf("   Total Tokens: %d\n", len(tokens))
	fmt.Printf("   Prompt Tokens: %d\n", len(encodeText(longPrompt, vocab)))
	fmt.Printf("   Generated Tokens: %d\n", len(tokens)-len(encodeText(longPrompt, vocab)))

	// Token 분석
	fmt.Println("\n📈 Token Distribution:")
	tokenCounts := make(map[int]int)
	for _, t := range tokens {
		tokenCounts[t]++
	}

	count := 0
	for token, freq := range tokenCounts {
		if count < 5 {
			if ch, ok := revVocab[token]; ok {
				fmt.Printf("   '%s': %d times\n", ch, freq)
			}
		}
		count++
	}

	fmt.Println("\n✅ Text generation tests complete!")
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

