	mux := http.DefaultServeMux
	RegisterTrainingRoutes(mux)
	RegisterDashboardRoute(mux)
	RegisterMonitoringRoutes(mux)
	RegisterCheckpointRoutes(mux)
	RegisterEvaluationRoutes(mux)

	// API 엔드포인트
	http.HandleFunc("/health", handleHealth)
	http.HandleFunc("/models", handleModelInfo)
	http.HandleFunc("/api/generate", handleGenerate)
	http.HandleFunc("/api/encode", handleEncode)
